586	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
587	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
588	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
589	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
590	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
591	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
592		if accountID == "" {
593			return Bill{}, invalidf("account id is empty")
594		}
595		if period.Month < time.January || period.Month > time.December {
596			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
597		}
598		s.mu.Lock()
599		defer s.mu.Unlock()
600	
601		acc, ok := s.accounts[accountID]
602		if !ok {
603			return Bill{}, ErrAccountNotFound
604		}
605		if existing, ok := acc.bills[period]; ok {
606			return existing.bill, nil
607		}
608	
609		now := s.nowUTC()
610		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
611		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
612		// 也不会被后来的订阅覆盖。
613		s.settleLocked(acc, now)
614	
615		if acc.sub == nil && len(acc.history) == 0 {
616			return Bill{}, ErrSubscriptionNotFound
617		}
618		if period.End().After(now) {
619			return Bill{}, ErrBillMonthNotEnded
620		}
621	
622		sub := segmentCoveringMonthLocked(acc, period)
623		if sub == nil {
624			// 早于首段开通，或处于两段订阅之间的空档。
625			return Bill{}, ErrBillBeforeSubscription
626		}
627	
628		terms := termsForPeriod(sub, period)
629		bill, err := buildBill(accountID, period, terms, acc.usage[period])
630		if err != nil {
631			return Bill{}, err
632		}
633		acc.bills[period] = &billRecord{bill: bill}
634		return bill, nil
635	}
