746	// EstimateCurrentBill 返回账户当前账期（服务当前时刻所在的 UTC 自然月）
747	// 截至查询时刻的预计账单。结果明确标为预估（Estimated 恒为 true）：账期
748	// 不必结束，也不需要先出账，按已接收的当月累计用量试算；没有任何用量时
749	// 也能查询，累计与超额用量为零，完整月费与税额照常计算。
750	//
751	// 计价完全沿用正式出账规则（与 CreateBill 同一套计算）：使用订阅保存的
752	// 当月套餐条件快照，收取完整月费并提供完整额度，月中开通也不按天折算；
753	// 超过额度的部分按快照中的超额单价计费；税额以月费与超额费用之和为基数，
754	// 按万分比税率四舍五入到分。尚未生效的换套餐安排不会提前混入——它只在
755	// 生效月月初 settleLocked 落入条件时间线后才成为当月条件，直接查询即可
756	// 使用安排接受时锁定的快照，不依赖先上报用量；之后修改套餐定义同样不改
757	// 写已保存的订阅或安排快照。
758	//
759	// 查询是纯读操作：不保存正式账单、不关闭当月、不产生欠费，也不改变已有
760	// 账单的金额与付款状态，更不会解除欠费停用。查询之后同月合法的新用量仍
761	// 按原规则接收，换套餐与取消安排仍按原时刻生效；正式出账继续只处理已经
762	// 结束的月份。已登记按月取消但尚未到终止时刻的账户当月完整计费、仍可
763	// 查询；因欠费暂停接收新用量但订阅仍生效的账户也可查询。
764	//
765	// 超额费用、税前合计或预计应付金额超出非负 int64 范围时返回 ErrOverflow，
766	// 不返回部分金额，也不留任何副作用。
767	//
768	// 账户不存在返回 ErrAccountNotFound；从未开通、订阅已经终止（含已到终止
769	// 时刻）返回 ErrSubscriptionNotFound；提前登记但开通时刻尚未到达返回
770	// ErrSubscriptionNotActivated——这些情况都不输出预估。
771	func (s *Service) EstimateCurrentBill(accountID string) (EstimatedBill, error) {
772		if accountID == "" {
773			return EstimatedBill{}, invalidf("account id is empty")
774		}
775		s.mu.Lock()
776		defer s.mu.Unlock()
777	
778		acc, ok := s.accounts[accountID]
779		if !ok {
780			return EstimatedBill{}, ErrAccountNotFound
781		}
782	
783		now := s.nowUTC()
784		// 与其他入口保持一致：查询即让已到生效时刻的换套餐安排落入条件
785		// 时间线、让已到终止时刻的取消生效。这一步只推进订阅自身状态，
786		// 不生成账单、不改变用量与付款。
787		s.settleLocked(acc, now)
788	
789		// 从未开通，或当前订阅段已到终止时刻（settleLocked 已移入 history），
790		// 都按无订阅处理；提前登记、开通时刻未到单独报尚未生效。
791		// 两种情况都不输出预估。
792		if acc.sub == nil {
793			return EstimatedBill{}, ErrSubscriptionNotFound
794		}
795		if now.Before(acc.sub.activatedAt) {
796			return EstimatedBill{}, ErrSubscriptionNotActivated
797		}
798	
799		// 预估只针对服务当前时刻所在的 UTC 自然月；条件、用量都只取当月。
800		period := MonthOf(now)
801		terms := termsForPeriod(acc.sub, period)
802		a, err := computeBillAmounts(terms, acc.usage[period])
803		if err != nil {
804			return EstimatedBill{}, err
805		}
806		return EstimatedBill{
807			AccountID:         accountID,
808			Estimated:         true,
809			Period:            period,
810			Terms:             terms,
811			TotalUsage:        a.totalUsage,
812			IncludedUnits:     a.includedUnits,
813			OverageUnits:      a.overageUnits,
814			MonthlyFee:        a.monthlyFee,
815			OverageFee:        a.overageFee,
816			Tax:               a.tax,
817			EstimatedTotalDue: a.totalDue,
818		}, nil
819	}
