1	package meter
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件为“换套餐安排的生效账期由接受请求时刻的下一个 UTC 自然月决定”
10	// 提供时区维度的回归保障：请求时刻的本地钟面月份与 UTC 月份不一致时，
11	// 生效账期、当前条件、待生效安排与实际切换月份必须全部按 UTC 自然月判定，
12	// 同一瞬间换任何时区表示都得到相同结果，且不依赖运行当天日期与机器默认时区。
13	//
14	// 甲：月费 1000 分、包含 10 单位、超额单价 100 分、税率 0。
15	// 乙：月费 2000 分、包含 20 单位、超额单价 200 分、税率 0。
16	var (
17		planJia = planDef("a", 1000, 10, 100, 0)
18		planYi  = planDef("b", 2000, 20, 200, 0)
19	)
20	
21	// newJiaYiService 创建账户 u：自 2026-01-01 起使用甲套餐，无欠费、无取消安排。
22	// 时钟由调用方随后设定到需要的请求时刻。
23	func newJiaYiService(t *testing.T) (*Service, *fakeClock) {
24		t.Helper()
25		s, clk := newTestService(utc(2026, 1, 1, 0, 0))
26		mustPlan(t, s, planJia)
27		mustPlan(t, s, planYi)
28		mustAccount(t, s, "u")
29		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
30		return s, clk
31	}
32	
33	// TestSchedulePlanChangeWhenLocalDateCrossesUTCMonth 锁定：2026-02-01 07:30（UTC+8）
34	// 首次安排改用乙时，该瞬间仍是 UTC 一月末（2026-01-31 23:30 UTC），生效账期
35	// 必须是二月而非三月；即使本地钟面已经进入二月，当前条件仍为甲、待生效条件为乙。
36	// 同一瞬间以 UTC 或其他时区表示，条件相同的账户必须得到完全相同的结果。
37	func TestSchedulePlanChangeWhenLocalDateCrossesUTCMonth(t *testing.T) {
38		// 同一实际瞬间 2026-01-31 23:30:00 UTC 的四种时区表示。
39		// +08:00 与 +05:30 的本地钟面已经进入 2 月 1 日，UTC 与 -05:00 仍在 1 月 31 日。
40		instant := utc(2026, 1, 31, 23, 30)
41		representations := map[string]time.Time{
42			"UTC":      instant,
43			"UTC+8":    time.Date(2026, time.February, 1, 7, 30, 0, 0, zonePlus8),
44			"UTC-5":    time.Date(2026, time.January, 31, 18, 30, 0, 0, zoneMinus5),
45			"UTC+5:30": time.Date(2026, time.February, 1, 5, 0, 0, 0, zonePlus530),
46		}
47		for name, at := range representations {
48			if !at.Equal(instant) {
49				t.Fatalf("%s representation %v is not instant %v", name, at, instant)
50			}
51		}
52		// 锁定测试前提：+08 表示的本地日期已是 2 月 1 日，而 UTC 仍是 1 月 31 日——
53		// 任何按本地月份决定生效账期的实现都会在此暴露。
54		if representations["UTC+8"].Day() != 1 || representations["UTC+8"].Month() != time.February {
55			t.Fatalf("plus8 wall clock = %v, want 2026-02-01", representations["UTC+8"])
56		}
57		if instant.Day() != 31 || instant.Month() != time.January {
58			t.Fatalf("utc wall clock = %v, want 2026-01-31", instant)
59		}
60	
61		wantChange := PlanChange{
62			TargetPlanID:    "b",
63			Terms:           termsOf(planYi),
64			EffectivePeriod: feb(2026),
65		}
66		wantCurrent := termsOf(planJia)
67	
68		var wantResult *PlanChangeResult
69		for name, at := range representations {
70			s, clk := newJiaYiService(t)
71			// 时钟以该时区表示返回同一瞬间；服务内部必须按 UTC 判定月份。
72			clk.t = at
73	
74			r, err := s.SchedulePlanChange("u", "b")
75			if err != nil {
76				t.Fatalf("%s: schedule: %v", name, err)
77			}
78			if !r.Created || r.Change != wantChange {
79				t.Fatalf("%s: schedule = %+v, want created change %+v", name, r, wantChange)
80			}
81			if wantResult == nil {
82				got := r
83				wantResult = &got
84			} else if r != *wantResult {
85				t.Fatalf("%s: result %+v differs from UTC result %+v", name, r, *wantResult)
86			}
87	
88			// 即使本地钟面已经进入二月，当前条件仍为甲、待生效条件为乙。
89			st, err := s.Status("u")
90			if err != nil {
91				t.Fatalf("%s: status: %v", name, err)
92			}
93			if st.CurrentTerms != wantCurrent {
94				t.Fatalf("%s: current = %+v, want %+v", name, st.CurrentTerms, wantCurrent)
95			}
96			if st.PendingChange == nil || *st.PendingChange != wantChange {
97				t.Fatalf("%s: pending = %+v, want %+v", name, st.PendingChange, wantChange)
98			}
99		}
100	}
101	
102	// TestSchedulePlanChangeExactlyAtUTCMonthStart 锁定：2026-01-31 19:00（UTC-5）
103	// 恰好是 UTC 二月月初零点（2026-02-01 00:00 UTC）。尚无待生效安排的账户
104	// 此刻首次安排改用乙，新安排必须从三月生效，二月继续使用甲套餐——
105	// 不能按本地钟面的一月把生效账期定成二月。
106	func TestSchedulePlanChangeExactlyAtUTCMonthStart(t *testing.T) {
107		s, clk := newJiaYiService(t)
108		// 本地钟面 2026-01-31 19:00（UTC-5）== 2026-02-01 00:00:00 UTC。
109		at := time.Date(2026, time.January, 31, 19, 0, 0, 0, zoneMinus5)
110		if !at.UTC().Equal(utc(2026, 2, 1, 0, 0)) {
111			t.Fatalf("request instant = %v, want 2026-02-01 00:00 UTC", at.UTC())
112		}
113		if at.Month() != time.January {
114			t.Fatalf("request wall month = %s, want January", at.Month())
115		}
116		clk.t = at
117	
118		r, err := s.SchedulePlanChange("u", "b")
119		if err != nil {
120			t.Fatalf("schedule: %v", err)
121		}
122		wantChange := PlanChange{
123			TargetPlanID:    "b",
124			Terms:           termsOf(planYi),
125			EffectivePeriod: mar(2026),
126		}
127		if !r.Created || r.Change != wantChange {
128			t.Fatalf("schedule = %+v, want created change %+v", r, wantChange)
129		}
130	
131		// 当前（二月）条件仍为甲，待生效安排为三月生效的乙。
132		st, err := s.Status("u")
133		if err != nil {
134			t.Fatal(err)
135		}
136		if st.CurrentTerms != termsOf(planJia) {
137			t.Fatalf("feb current = %+v, want %+v", st.CurrentTerms, termsOf(planJia))
138		}
139		if st.PendingChange == nil || *st.PendingChange != wantChange {
140			t.Fatalf("pending = %+v, want %+v", st.PendingChange, wantChange)
141		}
142	
143		// 二月中旬再查：仍是甲，安排仍等待三月生效。
144		clk.t = utc(2026, 2, 15, 12, 0)
145		st, _ = s.Status("u")
146		if st.CurrentTerms != termsOf(planJia) || st.PendingChange == nil || *st.PendingChange != wantChange {
147			t.Fatalf("mid-feb: current=%+v pending=%+v", st.CurrentTerms, st.PendingChange)
148		}
149	
150		// 三月月初零点：乙生效，待生效安排消失。
151		clk.t = utc(2026, 3, 1, 0, 0)
152		st, _ = s.Status("u")
153		if st.CurrentTerms != termsOf(planYi) || st.PendingChange != nil {
154			t.Fatalf("mar: current=%+v pending=%+v", st.CurrentTerms, st.PendingChange)
155		}
156	}
157	
158	// TestPlanChangeEffectiveInstantUTCBoundary 锁定生效瞬间的纳秒级边界：
159	// 对一月末已接受的二月安排，二月月初前最后一纳秒查询仍显示甲和待生效安排；
160	// 恰到 2026-02-01 00:00 UTC，直接查询即显示乙的完整条件、待生效安排消失，
161	// 无需先接收用量或出账。同一瞬间用带时区的时间表达也不能提前或延后切换；
162	// 在该瞬间再次选择乙必须返回 ErrPlanChangeSamePlan，不得新建三月安排。
163	func TestPlanChangeEffectiveInstantUTCBoundary(t *testing.T) {
164		s, clk := newJiaYiService(t)
165		// 一月末接受二月生效的安排。
166		clk.t = utc(2026, 1, 31, 12, 0)
167		r := mustSchedule(t, s, "u", "b")
168		wantChange := PlanChange{
169			TargetPlanID:    "b",
170			Terms:           termsOf(planYi),
171			EffectivePeriod: feb(2026),
172		}
173		if !r.Created || r.Change != wantChange {
174			t.Fatalf("schedule = %+v, want %+v", r, wantChange)
175		}
176	
177		// 二月月初零点的同一瞬间与前一纳秒，各取两种时区表示。
178		exact := utc(2026, 2, 1, 0, 0)
179		before := exact.Add(-time.Nanosecond)
180		exactPlus8 := time.Date(2026, time.February, 1, 8, 0, 0, 0, zonePlus8)
181		beforePlus8 := time.Date(2026, time.February, 1, 7, 59, 59, 999999999, zonePlus8)
182		if !exactPlus8.Equal(exact) || !beforePlus8.Equal(before) {
183			t.Fatal("test setup: zoned representations are not the expected instants")
184		}
185	
186		// 月初前最后一纳秒：无论 UTC 还是 +08:00 表示，都仍显示甲和待生效安排。
187		for _, at := range []time.Time{before, beforePlus8} {
188			clk.t = at
189			st, err := s.Status("u")
190			if err != nil {
191				t.Fatal(err)
192			}
193			if st.CurrentTerms != termsOf(planJia) {
194				t.Fatalf("at %v: current = %+v, want %+v", at, st.CurrentTerms, termsOf(planJia))
195			}
196			if st.PendingChange == nil || *st.PendingChange != wantChange {
197				t.Fatalf("at %v: pending = %+v, want %+v", at, st.PendingChange, wantChange)
198			}
199		}
200	
201		// 恰到 2026-02-01 00:00 UTC：直接查询（未接收用量、未出账）即显示
202		// 乙的完整条件，待生效安排消失；换 +08:00 表示的同一瞬间结果相同。
203		for _, at := range []time.Time{exact, exactPlus8} {
204			clk.t = at
205			st, err := s.Status("u")
206			if err != nil {
207				t.Fatal(err)
208			}
209			if st.CurrentTerms != termsOf(planYi) {
