221			t.Fatalf("re-select b at effective instant = %v, want ErrPlanChangeSamePlan", err)
222		}
223		st, err := s.Status("u")
224		if err != nil {
225			t.Fatal(err)
226		}
227		if st.CurrentTerms != termsOf(planYi) || st.PendingChange != nil {
228			t.Fatalf("after same-plan rejection: current=%+v pending=%+v", st.CurrentTerms, st.PendingChange)
229		}
230	}
231	
232	// TestPlanChangeBillingUsesEffectiveMonthTerms 用账单锁定切换月份的影响：
233	// 二月生效的安排下，一月用量 15 单位的账单按甲应付 1500 分，
234	// 二月用量 25 单位的账单按乙应付 3000 分；账单采用对应月份的完整套餐条件，
235	// 按整月收费和提供额度。账期结束后生成账单时，时钟使用其他时区也不能
